// Wiederverwendbarer Farb-Ringpuffer für Per-Frame-Berechnungen (vermeidet GC-Spitzen durch
// dutzende `new THREE.Color()` pro Frame). Nur für kurzlebige Zwischenwerte innerhalb eines Aufrufs!
const _SCRATCH_COLORS = Array.from({ length: 48 }, () => new THREE.Color());
let _scratchColorIdx = 0;
function scratchColor(value = 0x000000) {
  const c = _SCRATCH_COLORS[_scratchColorIdx];
  _scratchColorIdx = (_scratchColorIdx + 1) % _SCRATCH_COLORS.length;
  return c.set(value);
}

