  setMountAppearance(skinKey = 'horse_lvl1', horseLevel = 1) {
    const cfg = this.getHorseSkinConfig(skinKey, horseLevel);
    const validSkin = cfg.key;
    this.customMountSkin = validSkin;
    try {
      localStorage.setItem('aeryndor_mount_skin_v1', validSkin);
    } catch (_) {}

    const mg = this.localPlayerActor?.mountGroup;
    if (!mg) return;
    const targetGlb = cfg.glb || '/assets/models/npcs/pewi_mount_horse.glb';
    if (
      mg.userData.mountSkin === validSkin &&
      (mg.userData.glbActor || (mg.userData._glbIsLoading && mg.userData._glbLoadingUrl === targetGlb))
    ) {
      return;
    }
    mg.userData.mountSkin = validSkin;
    for (let i = mg.children.length - 1; i >= 0; i--) {
      const ch = mg.children[i];
      if (ch.isGroup) {
        mg.remove(ch);
      }
    }
    mg.userData.glbActor = null;
    mg.userData._activeGlbRigGroup = null;
    mg.userData._glbIsLoading = false;
    this.attachGLBModelToGroup(
      mg,
      targetGlb,
      cfg.tex || [`/assets/models/npcs/${cfg.texFile}`],
      cfg.height || 1.92,
      null,
      false,
      {
        color: cfg.color.clone(),
        emissive: cfg.emissive.clone(),
        emissiveIntensity: cfg.emissiveIntensity,
        useMapAsEmissive: true,
        roughness: cfg.roughness,
        metalness: cfg.metalness,
      }
    );
  }

  mountCompanionPreview(container, opts = {}) {
    if (!container) return;
    const mode = opts.mode === 'mount' ? 'mount' : 'pet';
    const horseLevel = Number(opts.horseLevel || 1);
    const rawSkinKey = opts.skinKey || (mode === 'mount' ? 'none' : 'ridack_dragonpet');
    const resolvedCfg =
      mode === 'mount'
        ? this.getHorseSkinConfig(rawSkinKey, horseLevel)
        : this.getPetSkinConfig(rawSkinKey);
    const sig = `${mode}:${resolvedCfg.key}`;

    if (!this._compPreview) {
      const scene = new THREE.Scene();
      const camera = new THREE.PerspectiveCamera(35, 1.0, 0.1, 30);
      const renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      renderer.toneMapping = THREE.ACESFilmicToneMapping;
      renderer.toneMappingExposure = 1.26;

      const hemi = new THREE.HemisphereLight(0xfef08a, 0x1e293b, 1.35);
      scene.add(hemi);
      const keyLight = new THREE.DirectionalLight(0xfffbeb, 2.05);
      keyLight.position.set(3.2, 5.2, 4.2);
      scene.add(keyLight);
      const rimLight = new THREE.PointLight(0x38bdf8, 2.4, 12);
      rimLight.position.set(-2.6, 2.5, -2.4);
      scene.add(rimLight);

      const pedestal = new THREE.Group();
      const disk = new THREE.Mesh(
        new THREE.CylinderGeometry(1.02, 1.14, 0.12, 36),
        new THREE.MeshStandardMaterial({ color: 0x0f172a, roughness: 0.38, metalness: 0.62 })
      );
      disk.position.y = -0.06;
      const ringOuter = new THREE.Mesh(
        new THREE.RingGeometry(0.95, 1.05, 48),
        new THREE.MeshBasicMaterial({ color: 0xf59e0b, side: THREE.DoubleSide, transparent: true, opacity: 0.78 })
      );
      ringOuter.rotation.x = -Math.PI / 2;
      ringOuter.position.y = 0.01;
      const ringInner = new THREE.Mesh(
        new THREE.RingGeometry(0.64, 0.72, 36),
        new THREE.MeshBasicMaterial({ color: 0x38bdf8, side: THREE.DoubleSide, transparent: true, opacity: 0.65 })
      );
      ringInner.rotation.x = -Math.PI / 2;
      ringInner.position.y = 0.015;
      pedestal.add(disk, ringOuter, ringInner);
      scene.add(pedestal);

      const modelRoot = new THREE.Group();
      scene.add(modelRoot);

      const state = {
        scene,
        camera,
        renderer,
        ringOuter,
        ringInner,
        modelRoot,
        sig: '',
        rotY: 0.42,
        targetRotY: 0.42,
        dragging: false,
        prevX: 0,
        clock: new THREE.Clock(),
        rafId: null,
        container: null,
        abort: new AbortController(),
      };
      const previewSignal = { signal: state.abort.signal };

      const dom = renderer.domElement;
      dom.style.cssText = 'width:100%;height:100%;display:block;cursor:grab;';
      dom.addEventListener('pointerdown', (ev) => {
        state.dragging = true;
        state.prevX = ev.clientX;
        dom.style.cursor = 'grabbing';
      }, previewSignal);
      window.addEventListener('pointermove', (ev) => {
        if (!state.dragging) return;
        const dx = ev.clientX - state.prevX;
        state.prevX = ev.clientX;
        state.targetRotY += dx * 0.014;
      }, previewSignal);
      window.addEventListener('pointerup', () => {
        if (state.dragging) {
          state.dragging = false;
          dom.style.cursor = 'grab';
        }
      }, previewSignal);

      const tickPreview = () => {
        state.rafId = requestAnimationFrame(tickPreview);
        if (!state.container || !document.body.contains(state.container)) return;
        const winPet = document.getElementById('win-pet');
        if (winPet && winPet.classList.contains('hidden')) return;
        const dt = Math.min(0.08, state.clock.getDelta());
        const t = state.clock.getElapsedTime();
        if (!state.dragging) {
          state.targetRotY += dt * 0.35;
        }
        state.rotY += (state.targetRotY - state.rotY) * Math.min(1.0, dt * 10.0);
        state.modelRoot.rotation.y = state.rotY;
        state.ringOuter.rotation.z = t * 0.55;
        state.ringInner.rotation.z = -t * 0.85;
        const glbAct = state.modelRoot.userData?.glbActor;
        if (glbAct && glbAct.mixer) {
          const idleKey = glbAct.clips?.wait ? 'wait' : glbAct.clips?.walk ? 'walk' : Object.keys(glbAct.clips || glbAct.actions || {})[0];
          if (idleKey) glbAct.playAnim(idleKey, 0.2);
          glbAct.mixer.update(dt);
        }
        state.renderer.render(state.scene, state.camera);
      };
      tickPreview();
      this._compPreview = state;
    }

    const st = this._compPreview;
    st.container = container;
    const w = Math.max(180, container.clientWidth || 216);
    const h = Math.max(150, container.clientHeight || 184);
    st.camera.aspect = w / h;
    if (mode === 'mount') {
      st.camera.position.set(0, 1.38, 3.85);
      st.camera.lookAt(0, 0.88, 0);
    } else {
      st.camera.position.set(0, 1.16, 3.15);
      st.camera.lookAt(0, 0.72, 0);
    }
    st.camera.updateProjectionMatrix();
    st.renderer.setSize(w, h);

    if (st.renderer.domElement.parentElement !== container) {
      container.innerHTML = '';
      container.appendChild(st.renderer.domElement);
    }

    if (st.sig !== sig) {
      st.sig = sig;
      for (let i = st.modelRoot.children.length - 1; i >= 0; i--) {
        st.modelRoot.remove(st.modelRoot.children[i]);
      }
      st.modelRoot.userData.glbActor = null;
      st.modelRoot.position.y = mode === 'pet' ? (resolvedCfg.previewYOffset ?? 0) : 0;
      this.attachGLBModelToGroup(
        st.modelRoot,
        resolvedCfg.glb,
        resolvedCfg.tex || [`/assets/models/npcs/${resolvedCfg.texFile}`],
        mode === 'mount' ? (resolvedCfg.height || 1.92) * 0.88 : (resolvedCfg.height || 1.42) * 0.96,
        null,
        false,
        {
          color: resolvedCfg.color.clone(),
          emissive: resolvedCfg.emissive.clone(),
          emissiveIntensity: resolvedCfg.emissiveIntensity,
          useMapAsEmissive: true,
          roughness: resolvedCfg.roughness ?? 0.46,
          metalness: resolvedCfg.metalness ?? 0.08,
          alphaTest: resolvedCfg.alphaTest || 0,
        }
      );
    }
  }

